"use client";
/* Shibe, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Shibe(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("shibe"); }, []);
  return React.createElement("piix-pal", { "pal": "shibe", ...piixAttrs(props) });
}

export default Shibe;
